  async function shuffleQueue() { const next = [...queue]; for (let index = next.length - 1; index > 0; index -= 1) { const target = Math.floor(Math.random() * (index + 1)); [next[index], next[target]] = [next[target], next[index]]; } setQueue(next); await persistQueue(next); }
  async function activateProfile(rawName: string) { const name = rawName.trim().slice(0, 80); if (!name || unavailableProfiles.has(name)) return; const existing = queue.find(item => item.toLocaleLowerCase() === name.toLocaleLowerCase()); const profileName = existing ?? name; try { localStorage.setItem(PROFILE_STORAGE_KEY, profileName); } catch { /* The current session still works if storage is unavailable. */ } setEmployee(profileName); setQueueActor(profileName); setProfileSelectorOpen(false); setView('calculator'); if (!existing) { const nextQueue = [...queue, profileName]; setQueue(nextQueue); await persistQueue(nextQueue); } }
